ALTER TABLE "Product" ADD COLUMN "category" TEXT;
ALTER TABLE "Product" ADD COLUMN "sku" TEXT;
ALTER TABLE "Product" ADD COLUMN "barcode" TEXT;
ALTER TABLE "Product" ADD COLUMN "unit" TEXT NOT NULL DEFAULT 'piece';
ALTER TABLE "Product" ADD COLUMN "costPrice" DECIMAL(12,2) NOT NULL DEFAULT 0;
ALTER TABLE "Product" ADD COLUMN "minimumStock" DECIMAL(12,2) NOT NULL DEFAULT 0;
ALTER TABLE "Product" ADD COLUMN "targetStock" DECIMAL(12,2) NOT NULL DEFAULT 0;
ALTER TABLE "Product" ADD COLUMN "trackExpiry" BOOLEAN NOT NULL DEFAULT false;
CREATE UNIQUE INDEX "Product_sku_key" ON "Product"("sku") WHERE "sku" IS NOT NULL;
CREATE UNIQUE INDEX "Product_barcode_key" ON "Product"("barcode") WHERE "barcode" IS NOT NULL;
CREATE TYPE "StockMovementType" AS ENUM ('RECEIVED','SOLD','RETURNED','DAMAGED','EXPIRED','ADJUSTMENT');
CREATE TABLE "ProductBatch" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"batchNumber" TEXT NOT NULL,"receivedQuantity" DECIMAL(12,2) NOT NULL,"remainingQuantity" DECIMAL(12,2) NOT NULL,"receivedDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expirationDate" TIMESTAMP(3),"supplier" TEXT,"purchaseCost" DECIMAL(12,2) NOT NULL,CONSTRAINT "ProductBatch_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ProductBatch_productId_batchNumber_key" ON "ProductBatch"("productId","batchNumber");
CREATE INDEX "ProductBatch_expirationDate_idx" ON "ProductBatch"("expirationDate");
CREATE INDEX "ProductBatch_productId_remainingQuantity_idx" ON "ProductBatch"("productId","remainingQuantity");
ALTER TABLE "ProductBatch" ADD CONSTRAINT "ProductBatch_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "StockMovement" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"batchId" TEXT,"type" "StockMovementType" NOT NULL,"quantity" DECIMAL(12,2) NOT NULL,"reason" TEXT,"reference" TEXT,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StockMovement_pkey" PRIMARY KEY ("id"));
CREATE INDEX "StockMovement_productId_createdAt_idx" ON "StockMovement"("productId","createdAt");
CREATE INDEX "StockMovement_batchId_createdAt_idx" ON "StockMovement"("batchId","createdAt");
ALTER TABLE "StockMovement" ADD CONSTRAINT "StockMovement_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "StockMovement" ADD CONSTRAINT "StockMovement_batchId_fkey" FOREIGN KEY ("batchId") REFERENCES "ProductBatch"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
